public class DogTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Dog rex = new Dog("Rex");
        check("getName() is inherited", "Rex", rex.getName());
        check("speak() is overridden", "Woof!", rex.speak());
        check("fetch()", "Rex fetches the ball!", rex.fetch());

        Animal buddy = new Dog("Buddy");
        check("getName() through an Animal reference", "Buddy", buddy.getName());
        check("speak() through an Animal reference", "Woof!", buddy.speak());

        Animal plain = new Animal("Generic");
        check("a plain Animal still says ...", "...", plain.speak());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

